"use strict";(()=>{var e=t=>document.getElementById(t);chrome.storage.sync.get(["relay","token","seal","redact"]).then(t=>{e("relay").value=String(t.relay??""),e("token").value=String(t.token??""),e("seal").checked=t.seal===!0,e("redact").checked=t.redact!==!1});e("save").addEventListener("click",async()=>{let t=e("relay").value.trim().replace(/\/$/,"");if(t&&!await chrome.permissions.request({origins:[new URL(t).origin+"/*"]}).catch(()=>!1))return void(e("st").textContent="Permission to reach the relay was not granted.");await chrome.storage.sync.set({relay:t,token:e("token").value,seal:e("seal").checked,redact:e("redact").checked}),e("st").textContent="Saved."});})();
